        List<UExpression> args = call.getValueArguments();
        if (args.size() != 1) {
            return;
        }

        String layoutName = getLayoutNameFromExpression(args.get(0));
        if (layoutName != null) {
            UClass uClass = UastUtils.getContainingUClass(call);
            if (uClass != null && uClass.getName() != null) {
                activityToLayout.put(uClass.getName(), layoutName);
            }
        }
    }

    private String getLayoutNameFromExpression(UExpression expression) {
        String qName = expression.asRenderString();
        if (qName != null) {
            int idx = qName.indexOf(".R.layout.");
            if (idx != -1) {
                return qName.substring(idx + 10);
            }
            if (qName.startsWith("R.layout.")) {
                return qName.substring(9);
            }
        }
        return null;
    }

    @Override
    public void afterCheckEachProject(Context context) {
        for (Map.Entry<String, String> entry : activityToLayout.entrySet()) {
            String activityName = entry.getKey();
            String layoutName = entry.getValue();

            Location location = layoutsWithRootBackground.get(layoutName);
            if (location == null) {
                continue;
            }

            String theme = activityToTheme.get(activityName);
            if (theme == null) {
                theme = applicationTheme;
            }

            if (theme != null && !isTransparentTheme(theme)) {
                String message = String.format(
                        "Possible overdraw: Root element paints background `%s` with a theme that also paints a background (inferred theme is `%s`)",
                        layoutName, theme);
                context.report(ISSUE, location, message);
            }
        }
    }

    private boolean isTransparentTheme(String theme) {
        if (theme == null) {
            return false;
        }
        if (TRANSPARENT_THEMES.contains(theme)) {
            return true;
        }
        String lower = theme.toLowerCase(Locale.US);
        return lower.contains(".translucent") || lower.contains(".dialog") ||
               lower.contains(".panel") || lower.contains(".wallpaper") ||
               lower.contains("@null") || lower.contains("@android:color/transparent");
    }
}
